package com.procurement.compliance_engine.repository;
import com.procurement.compliance_engine.entity.TenderClassification;import com.procurement.compliance_engine.entity.Tender;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import java.util.*;
public interface TenderClassificationRepository extends JpaRepository<TenderClassification,UUID>{
 List<TenderClassification> findByJobIdOrderByRelevanceScoreDesc(UUID jobId);
 @Query("select c from TenderClassification c where c.tender.id=:tenderId and c.confirmed=true and c.job.status='COMPLETED'") List<TenderClassification> findConfirmedByTender(@Param("tenderId") UUID tenderId);
 @Query("select c from TenderClassification c where c.confirmed=true and c.job.status='COMPLETED' and c.sectorCode in :sectors and c.tender.status='PUBLISHED' and c.tender.submissionDeadline>CURRENT_TIMESTAMP") List<TenderClassification> findConfirmedOpenMatches(@Param("sectors") Collection<String> sectors);
 @Query(value="select distinct t from Tender t join TenderClassification c on c.tender.id=t.id where c.confirmed=true and c.job.status='COMPLETED' and c.sectorCode in :sectors and t.status='PUBLISHED' and t.submissionDeadline>CURRENT_TIMESTAMP and (:sector is null or c.sectorCode=:sector) and (:search is null or lower(t.title) like lower(concat('%',:search,'%')) or lower(coalesce(t.description,'')) like lower(concat('%',:search,'%')))",countQuery="select count(distinct t.id) from Tender t join TenderClassification c on c.tender.id=t.id where c.confirmed=true and c.job.status='COMPLETED' and c.sectorCode in :sectors and t.status='PUBLISHED' and t.submissionDeadline>CURRENT_TIMESTAMP and (:sector is null or c.sectorCode=:sector) and (:search is null or lower(t.title) like lower(concat('%',:search,'%')) or lower(coalesce(t.description,'')) like lower(concat('%',:search,'%')))") Page<Tender> findRecommendations(@Param("sectors") Collection<String> sectors,@Param("sector") String sector,@Param("search") String search,Pageable pageable);
}
